        $preview=Get-WsmWindowsSettingsReviewWorkspacePreview -Workspace $workspace -PairId $catalog.PairId -SourceInventoryPath $sourcePath -SourceInventoryHash $sourceHash -TargetInventoryPath $targetPath -TargetInventoryHash $targetHash -ReviewWindowsSettings:$false;Write-WsmJson $previewPath $preview;$previewHash=(Get-FileHash -LiteralPath $previewPath -Algorithm SHA256).Hash.ToLowerInvariant();$decisions=Get-WsmWindowsSettingsDecisionTemplate $preview;Write-WsmJson $decisionsPath $decisions;$decisionsHash=(Get-FileHash -LiteralPath $decisionsPath -Algorithm SHA256).Hash.ToLowerInvariant();$catalogPath=Get-WsmCatalogPath $workspace $catalog.PairId;$beforeApplyHash=(Get-FileHash -LiteralPath $catalogPath -Algorithm SHA256).Hash.ToLowerInvariant()
